const out=[];
for (const id of ['0:1','1:2']) {
  const p = await figma.getNodeByIdAsync(id);
  await figma.setCurrentPageAsync(p);
  out.push('=== '+p.name);
  const walk=(n,d)=>{
    let s='  '.repeat(d)+n.type+' '+n.id+' "'+n.name+'" '+(n.width?Math.round(n.width)+'x'+Math.round(n.height):'');
    if(n.type==='TEXT') s+=' :: '+n.characters.replace(/\n/g,' | ');
    if((n.type==='RECTANGLE'||n.type==='FRAME') && n.fills && n.fills.length && n.fills[0].type==='SOLID'){const c=n.fills[0].color; s+=' fill#'+[c.r,c.g,c.b].map(v=>Math.round(v*255).toString(16).padStart(2,'0')).join('');}
    out.push(s);
    if(n.children) for(const c of n.children) walk(c,d+1);
  };
  for(const c of p.children) walk(c,0);
}
return out.join('\n');

const out=[];
for (const id of ['1:3','1:4','6:2']) {
  const p = await figma.getNodeByIdAsync(id);
  await figma.setCurrentPageAsync(p);
  out.push('=== '+p.name);
  const walk=(n,d)=>{
    let s='  '.repeat(d)+n.type+' '+n.id+' "'+n.name+'" '+(n.width!==undefined?Math.round(n.width)+'x'+Math.round(n.height):'');
    if(n.type==='TEXT') s+=' :: '+n.characters.slice(0,60)+' font:'+JSON.stringify(n.fontName)+' '+String(n.fontSize);
    if(n.fills && n.fills!==figma.mixed && n.fills.length) s+=' fills:'+n.fills.map(f=>f.type).join(',');
    out.push(s);
    if(n.children && d<3 && !(n.type==='COMPONENT' && d>1)) for(const c of n.children) walk(c,d+1);
  };
  for(const c of p.children) walk(c,0);
}
return out.join('\n');

