 if('layoutMode' in n) s+=' layout:'+n.layoutMode+' pad:'+[n.paddingTop,n.paddingRight,n.paddingBottom,n.paddingLeft]+' gap:'+n.itemSpacing+' r:'+String(n.cornerRadius)+' align:'+n.primaryAxisAlignItems+'/'+n.counterAxisAlignItems+' sizing:'+n.primaryAxisSizingMode+'/'+n.counterAxisSizingMode;
 if(n.fills&&n.fills!==figma.mixed) s+=' fills:'+JSON.stringify(n.fills.map(f=>f.type==='SOLID'?{c:f.color,o:f.opacity}:{t:f.type,sm:f.scaleMode}));
 if(n.strokes&&n.strokes.length) s+=' strokes:'+JSON.stringify(n.strokes.map(f=>f.color))+' sw:'+String(n.strokeWeight);
 if(n.componentPropertyDefinitions) s+=' props:'+JSON.stringify(n.componentPropertyDefinitions);
 if(n.componentPropertyReferences) s+=' refs:'+JSON.stringify(n.componentPropertyReferences);
 out.push(s);
 if(n.children) n.children.forEach(c=>ser(c,d+1));
};
