const go=async(node,frame,dest)=>{let action; if(frame===dest){action={type:'NODE',destinationId:F[dest].children[0].id,navigation:'SCROLL_TO',transition:{type:'SMART_ANIMATE',easing:{type:'EASE_OUT'},duration:0.4},preserveScrollPosition:false};} else action={type:'NODE',destinationId:ids[dest],navigation:'NAVIGATE',transition:{type:'SMART_ANIMATE',easing:{type:'EASE_OUT'},duration:0.3},preserveScrollPosition:false}; await node.setReactionsAsync([{trigger:{type:'ON_CLICK'},actions:[action]}]);};
const log=[];
const link=async(frame,pred,dest,label)=>{const ns=F[frame].findAll(pred); for(const n of ns) await go(n,frame,dest); log.push(`${frame}:${label}→${dest} x${ns.length}`);};
const isCart=n=>n.name==='Cart'&&n.type==='INSTANCE'&&n.parent&&n.parent.name==='Actions';
for(const f of ['home','cat','prod','cart']){ await link(f,isCart,'cart','header cart'); await link(f,n=>n.type==='INSTANCE'&&n.name.startsWith('Card · '),'prod','product cards'); }
await link('home',n=>n.name==='Btn · Shop Now'||n.name.startsWith('Btn · View All')||n.name==='Tile · Casual','cat','Shop Now/View All/Casual');
await link('cat',n=>n.name==='Crumb · Home','home','crumb Home');
await link('prod',n=>n.name==='Btn · Add to Cart','cart','Add to Cart');
await link('prod',n=>n.name==='Crumb · Shop','cat','crumb Shop');
await link('prod',n=>n.name==='Crumb · Home','home','crumb Home');
await link('cart',n=>n.name==='Crumb · Home','home','crumb Home');
await link('cart',n=>n.type==='INSTANCE'&&n.name.startsWith('Item · '),'prod','cart items');
for(const f of ['cat','prod','cart']) await link(f,n=>n.type==='TEXT'&&n.name==='Wordmark'&&n.parent.type==='INSTANCE','home','wordmark');
P.flowStartingPoints=[{nodeId:ids.home,name:'SHOP.CO · Shopping flow'}];
return log;

const F=await figma.getNodeByIdAsync('18:1020'); const card=F.findOne(n=>n.type==='INSTANCE'&&n.name.startsWith('Card · ')); const bc=F.findOne(n=>n.name==='Breadcrumb'); const out=[];
for(const [dest,tr] of [[bc.id,null],[F.children[0].id,null],[bc.id,{type:'DISSOLVE',easing:{type:'EASE_OUT'},duration:0.3}]]){try{await card.setReactionsAsync([{trigger:{type:'ON_CLICK'},actions:[{type:'NODE',destinationId:dest,navigation:'SCROLL_TO',transition:tr,preserveScrollPosition:false}]}]); out.push('ok '+dest+' '+JSON.stringify(tr)); break;}catch(e){out.push(String(e).slice(0,120));}}
return out;

